import { h, raw, api, qs, state, win, level, toast, errorsBox, confirmDialog, modal, fmtDate, langName } from '../core.js';

const TABS = [['overview', 'Overview'], ['review', 'Review queue'], ['vocabulary', 'Vocabulary'], ['import', 'Import'], ['lists', 'Lists'], ['taxonomy', 'Topics & levels'], ['stories', 'Stories'], ['videos', 'Videos'], ['grammar', 'Grammar'], ['topics', 'Daily Topics'], ['jobs', 'Automation'], ['settings', 'Settings'], ['users', 'Users']];
const status = (s) => h`<span class="status-${s}">${s}</span>`;
const pairsToText = (arr) => (arr || []).map((c) => [c.ta, c.en, c.form].filter(Boolean).join(' | ')).join('\n');
const textToPairs = (t) => String(t || '').split('\n').map((l) => l.trim()).filter(Boolean).map((l) => { const [ta, en = '', form] = l.split('|').map((x) => x.trim()); return form ? { ta, en, form } : { ta, en }; });

export async function page({ params, query, navigate }) {
  const tab = params.tab || 'overview';
  const fn = { overview, review, vocabulary, import: importTab, lists, taxonomy, stories, videos, grammar: grammarTab, topics: topicsTab, jobs, settings, users }[tab];
  if (!fn) throw Object.assign(new Error('Unknown admin section'), { status: 404 });
  const view = await fn({ query, navigate });
  return {
    title: `Admin · ${TABS.find((t) => t[0] === tab)[1]}`, scene: 'fern', keepScroll: true,
    html: h`<div class="page-head"><div><h1>Content dashboard · ${langName()}</h1><p>Managing ${langName()} content. Switch the language at the top to manage another library.</p></div></div>
      ${win({ title: TABS.find((t) => t[0] === tab)[1], variant: 'salmon', corner: 'hibiscus', body: h`<nav class="tabs" aria-label="Admin sections">${TABS.map(([k, l]) => h`<a href="/admin/${k}" ${k === tab ? raw('aria-current="page"') : ''}>${l}</a>`)}</nav>${view.html}` })}`,
    mount: (root) => view.mount?.(root, () => navigate(location.pathname + location.search, { replace: true })),
  };
}

async function overview() {
  const o = await api('/admin/overview');
  const c = o.counts; const a = o.automation;
  const cnt = (x) => `${x.published || 0} published · ${x.pending || 0} pending · ${x.rejected || 0} rejected`;
  return {
    html: h`<div class="statgrid"><div class="stat"><b>${c.users}</b><span>accounts</span></div><div class="stat"><b>${c.sessions}</b><span>lessons started</span></div><div class="stat"><b>${(c.vocabulary.pending || 0) + (c.stories.pending || 0) + (c.videos.pending || 0)}</b><span>items awaiting review</span></div></div>
    <dl class="kv" style="margin-top:14px"><dt>Vocabulary</dt><dd>${cnt(c.vocabulary)}</dd><dt>Stories</dt><dd>${cnt(c.stories)}</dd><dt>Videos</dt><dd>${cnt(c.videos)}</dd></dl>
    <h3 style="margin-top:16px">Automation</h3>
    <dl class="kv"><dt>Scheduler</dt><dd>${a.enabled ? 'enabled' : 'disabled'}</dd><dt>AI provider</dt><dd>${a.ai.configured ? `${a.ai.provider} (${a.ai.model})` : h`not used — every feature works offline (word library, offline dictionary, practice stories, editor-written lessons). Optional: install Ollama and set OLLAMA_MODEL to also generate stories, grammar and richer word lists.`}</dd>
      <dt>YouTube discovery</dt><dd>${a.youtube.configured ? 'configured' : h`<span class="status-failed">not configured</span> — set YOUTUBE_API_KEY`}</dd><dt>Today (${a.today})</dt><dd>${a.plannedJobs.length ? a.plannedJobs.map((p) => h`${p.type}: ${p.status}<br>`) : h`no jobs planned<br>`}${a.skipped.map((s) => h`<span class="small muted">${s.type} skipped: ${s.reason}</span><br>`)}</dd></dl>
    <div class="btn-row" style="margin-top:12px"><a class="btn" href="/admin/review">Open review queue</a><a class="btn btn--cyan" href="/admin/jobs">Automation</a></div>`,
  };
}

async function review() {
  const q = await api(`/admin/review?lang=${state.lang}`);
  const act = (kind, id) => h`<div class="btn-row"><button class="btn btn--small btn--green" data-act="${kind}:${id}:published">Approve</button><button class="btn btn--small btn--danger" data-act="${kind}:${id}:rejected">Reject</button></div>`;
  const aiNote = (v) => (v?.aiReview ? h`<div class="small">AI review: ${v.aiReview.ok === true ? 'no issues' : v.aiReview.ok === false ? h`<span class="status-failed">issues</span>` : 'unavailable'} ${(v.aiReview.issues || []).join('; ')}</div>` : '');
  return {
    html: h`<p class="small muted">Nothing generated by AI is published until it is approved here. Check Tamil spelling, translation, naturalness and level.</p>
    <h3>Vocabulary (${q.vocabulary.length})</h3>${q.vocabulary.length ? h`<div class="table-wrap"><table class="tbl"><tr><th>Tamil</th><th>English / Hindi / Malayalam</th><th>Examples</th><th>Checks</th><th></th></tr>${q.vocabulary.map((v) => h`<tr><td><span class="ta" lang="ta">${v.tamil}</span><br><span class="small">${v.transliteration}</span><br>${level(v.level)} <span class="small">${v.partOfSpeech}</span></td><td>${v.english}<br><span class="small">${v.hindi} · ${v.malayalam}</span></td><td class="small">${v.examples.map((e) => h`<div><span class="ta" lang="ta">${e.ta}</span> — ${e.en}</div>`)}</td><td class="small">${(v.validation.warnings || []).join('; ')}${aiNote(v.validation)}</td><td>${act('vocabulary', v.id)}<a class="small" href="/admin/vocabulary?edit=${v.id}">Edit</a></td></tr>`)}</table></div>` : h`<p class="muted">No pending words.</p>`}
    <h3 style="margin-top:16px">Stories (${q.stories.length})</h3>${q.stories.length ? h`<ul class="list">${q.stories.map((s) => h`<li class="spread"><span><span class="ta" lang="ta">${s.title}</span> ${level(s.level)} <span class="small">${s.sourceType} · suggested ${s.validation.difficulty?.suggestedLevel || '?'}</span>${aiNote(s.validation)}</span><span class="row"><a class="btn btn--small btn--ghost" href="/admin/stories?edit=${s.id}">Read & edit</a>${act('stories', s.id)}</span></li>`)}</ul>` : h`<p class="muted">No pending stories.</p>`}
    <h3 style="margin-top:16px">Videos (${q.videos.length})</h3>${q.videos.length ? h`<ul class="list">${q.videos.map((v) => h`<li class="spread"><span><a href="${v.watchUrl}" target="_blank" rel="noopener">${v.title}</a> ${level(v.level)} <span class="small">${v.category} · ${v.channel} · ${v.validation.classification || ''}</span></span>${act('videos', v.id)}</li>`)}</ul>` : h`<p class="muted">No pending videos.</p>`}
    <h3 style="margin-top:16px">Grammar lessons (${q.grammar.length})</h3>${q.grammar.length ? h`<ul class="list">${q.grammar.map((g) => h`<li class="spread"><span>${g.title} ${level(g.level)} <span class="small">${g.source} · ${g.category || ''}</span>${aiNote(g.validation)}</span><span class="row"><a class="btn btn--small btn--ghost" href="/admin/grammar?edit=${g.id}">Read & edit</a>${act('grammar', g.id)}</span></li>`)}</ul>` : h`<p class="muted">No pending grammar lessons.</p>`}
    <h3 style="margin-top:16px">AI dictionary enrichments (${q.enrichments.length})</h3>${q.enrichments.length ? h`<ul class="list">${q.enrichments.map((e) => h`<li class="spread"><a href="/dictionary/entry/${e.id}"><span class="ta" lang="${e.lang}">${e.tamil}</span> ${e.english}</a><span class="row"><button class="btn btn--small btn--green" data-enr="${e.id}:1">Approve all</button><button class="btn btn--small btn--danger" data-enr="${e.id}:0">Discard</button></span></li>`)}</ul>` : h`<p class="muted">No pending enrichments.</p>`}
    <h3 style="margin-top:16px">AI vocabulary lists (${q.lists.length})</h3>${q.lists.length ? h`<ul class="list">${q.lists.map((l) => h`<li class="spread"><span>${l.title} ${level(l.level)}</span><button class="btn btn--small btn--green" data-publist="${l.id}">Publish list (approved words only)</button></li>`)}</ul>` : h`<p class="muted">No pending lists.</p>`}`,
    mount(root, reload) {
      root.addEventListener('click', async (e) => {
        const b = e.target.closest('[data-act]');
        const pl = e.target.closest('[data-publist]');
        const en = e.target.closest('[data-enr]');
        if (en) { const [id, ok] = en.dataset.enr.split(':'); try { await api(`/admin/dictionary/${id}/review`, { method: 'POST', body: { approve: ok === '1' } }); toast(ok === '1' ? 'Approved.' : 'Discarded.'); reload(); } catch (x) { toast(x.message, 'bad'); } return; }
        try {
          if (b) { const [kind, id, st] = b.dataset.act.split(':'); await api(`/admin/${kind}/${id}/status`, { method: 'POST', body: { status: st } }); toast(st === 'published' ? 'Approved and published.' : 'Rejected.'); reload(); }
          if (pl) { await api(`/admin/lists/${pl.dataset.publist}`, { method: 'PATCH', body: { status: 'published' } }); toast('List published.'); reload(); }
        } catch (x) { toast(x.message, 'bad'); }
      });
    },
  };
}

function vocabForm(v = {}) {
  const m = state.meta;
  const opt = (arr, cur) => arr.map(([val, lab]) => h`<option value="${val}" ${String(val) === String(cur ?? '') ? raw('selected') : ''}>${lab}</option>`);
  return h`<form data-vf><div class="grid grid-2" style="gap:0 14px">
    <label class="field"><span>Tamil *</span><input class="ta-input" name="tamil" value="${v.tamil || ''}" required></label>
    <label class="field"><span>Transliteration</span><input name="transliteration" value="${v.transliteration || ''}" placeholder="automatic"></label>
    <label class="field"><span>Pronunciation guide</span><input name="pronunciation" value="${v.pronunciation || ''}"></label>
    <label class="field"><span>English *</span><input name="english" value="${v.english || ''}" required></label>
    <label class="field"><span>Other English meanings</span><input name="alt_english" value="${(v.altEnglish || []).join(', ')}"></label>
    <label class="field"><span>Hindi</span><input name="hindi" value="${v.hindi || ''}" lang="hi"></label>
    <label class="field"><span>Malayalam</span><input name="malayalam" value="${v.malayalam || ''}" lang="ml"></label>
    <label class="field"><span>Part of speech *</span><select name="part_of_speech">${opt(m.partsOfSpeech.map((p) => [p, p]), v.partOfSpeech)}</select></label>
    <label class="field"><span>Level *</span><select name="level">${opt(m.levels.map((l) => [l.code, l.code]), v.level)}</select></label>
    <label class="field"><span>Topic</span><select name="topic_id"><option value="">—</option>${opt(m.topics.map((t) => [t.id, t.name]), v.topicId)}</select></label>
    <label class="field"><span>Register</span><select name="register">${opt(m.registers.map((r) => [r, r]), v.register || 'common')}</select></label>
    <label class="field"><span>Dialect / regional notes</span><input name="dialect" value="${v.dialect || ''}"></label>
    <label class="field"><span>Synonyms (Tamil)</span><input class="ta-input" name="synonyms" value="${(v.synonyms || []).join(', ')}"></label>
    <label class="field"><span>Antonyms (Tamil)</span><input class="ta-input" name="antonyms" value="${(v.antonyms || []).join(', ')}"></label></div>
    <label class="field"><span>Collocations — one per line: Tamil with [[target]] | English | form (verbs)</span><textarea class="ta-input" name="collocations">${pairsToText(v.collocations)}</textarea></label>
    <label class="field"><span>Example sentences — one per line: Tamil with [[target]] | English | form</span><textarea class="ta-input" name="examples">${pairsToText(v.examples)}</textarea></label>
    <label class="field"><span>Verb forms (JSON, verbs only)</span><input name="forms" value="${JSON.stringify(v.forms || {})}"></label>
    <div data-ai-out></div><div data-err></div>
    <div class="btn-row"><button class="btn btn--ghost" type="button" data-assist>${state.meta.features.ai ? 'AI: suggest translations & examples' : 'Fill from offline dictionary'}</button><button class="btn" type="submit">${v.id ? 'Save changes' : 'Create word'}</button></div></form>`;
}
function readVocabForm(f) {
  const d = Object.fromEntries(new FormData(f));
  let forms = {}; try { forms = JSON.parse(d.forms || '{}'); } catch { /* validated server-side */ }
  return { ...d, topic_id: d.topic_id ? Number(d.topic_id) : null, alt_english: d.alt_english, collocations: textToPairs(d.collocations), examples: textToPairs(d.examples), forms };
}
function bindVocabForm(el, onSave) {
  const f = el.querySelector('[data-vf]');
  f.addEventListener('submit', async (e) => { e.preventDefault(); try { await onSave(readVocabForm(f)); } catch (x) { el.querySelector('[data-err]').innerHTML = String(errorsBox(x)); } });
  el.querySelector('[data-assist]')?.addEventListener('click', async (e) => {
    const out = el.querySelector('[data-ai-out]'); e.target.disabled = true; out.textContent = state.meta.features.ai ? 'Asking AI…' : 'Looking up…';
    try {
      const r = await api('/admin/ai/translate', { method: 'POST', body: { tamil: f.tamil.value, english: f.english.value } });
      const s = r.suggestion;
      for (const k of ['english', 'hindi', 'malayalam', 'pronunciation']) if (s[k] && !f[k].value) f[k].value = s[k];
      if (s.collocations?.length && !f.collocations.value) f.collocations.value = pairsToText(s.collocations);
      if (s.examples?.length && !f.examples.value) f.examples.value = pairsToText(s.examples);
      out.innerHTML = String(h`<div class="notice">${r.provider === 'offline-dictionary' ? 'Filled empty fields from the offline dictionary and the pronunciation spelling. Check them before saving.' : 'AI suggestions filled empty fields only. They are unverified — check every line before saving.'}</div>`);
    } catch (x) { out.innerHTML = String(errorsBox(x)); }
    e.target.disabled = false;
  });
}

async function vocabulary({ query }) {
  const st = query.status || 'published';
  const r = await api(`/admin/vocabulary${qs({ q: query.q, status: st, page: query.page, level: query.level })}`);
  const editing = query.edit ? await api(`/admin/vocabulary/${query.edit}`) : null;
  return {
    html: h`<div class="btn-row" style="margin-bottom:10px"><button class="btn btn--bloom" data-new>Add word</button></div>
    <form class="filters" data-f><label class="field"><span>Search</span><input type="search" name="q" value="${query.q || ''}"></label><label class="field"><span>Status</span><select name="status">${['published', 'pending', 'rejected'].map((s) => h`<option ${s === st ? raw('selected') : ''}>${s}</option>`)}</select></label><button class="btn btn--cyan" type="submit">Filter</button></form>
    <p class="small muted">${r.total} entries</p>
    <div class="table-wrap"><table class="tbl"><tr><th>Tamil</th><th>English</th><th>Level</th><th>POS</th><th>Review</th><th>Source</th><th></th></tr>${r.items.map((v) => h`<tr><td><span class="ta" lang="ta">${v.tamil}</span></td><td>${v.english}</td><td>${v.level}</td><td>${v.partOfSpeech}</td><td class="small">${v.reviewStatus}</td><td class="small">${v.source}</td>
      <td><div class="btn-row"><button class="btn btn--small btn--ghost" data-edit="${v.id}">Edit</button>${v.reviewStatus !== 'native-reviewed' ? h`<button class="btn btn--small btn--green" data-native="${v.id}" title="Confirm a native speaker checked this entry">Mark native-reviewed</button>` : ''}<button class="btn btn--small btn--danger" data-del="${v.id}">Delete</button></div></td></tr>`)}</table></div>
    <div class="spread" style="margin-top:8px">${r.page > 1 ? h`<a class="btn btn--small btn--ghost" href="/admin/vocabulary${qs({ ...query, page: r.page - 1 })}">Previous</a>` : h`<span></span>`}<span class="small">Page ${r.page} / ${r.pages}</span>${r.page < r.pages ? h`<a class="btn btn--small btn--ghost" href="/admin/vocabulary${qs({ ...query, page: r.page + 1 })}">Next</a>` : h`<span></span>`}</div>`,
    mount(root, reload) {
      const open = (v) => modal({ title: v ? `Edit ${v.tamil}` : 'Add word', body: vocabForm(v || {}), onMount(el, close) {
        bindVocabForm(el, async (body) => { if (v) await api(`/admin/vocabulary/${v.id}`, { method: 'PATCH', body }); else await api('/admin/vocabulary', { method: 'POST', body }); close(); toast('Saved.'); reload(); });
      } });
      root.querySelector('[data-f]').addEventListener('submit', (e) => { e.preventDefault(); history.replaceState({}, '', `/admin/vocabulary${qs(Object.fromEntries(new FormData(e.target)))}`); reload(); });
      root.querySelector('[data-new]').addEventListener('click', () => open(null));
      root.addEventListener('click', async (e) => {
        const ed = e.target.closest('[data-edit]'); const del = e.target.closest('[data-del]'); const nat = e.target.closest('[data-native]');
        try {
          if (ed) open(await api(`/admin/vocabulary/${ed.dataset.edit}`));
          if (nat) { await api(`/admin/vocabulary/${nat.dataset.native}/status`, { method: 'POST', body: { status: 'published', reviewStatus: 'native-reviewed' } }); toast('Marked as native-reviewed.'); reload(); }
          if (del && await confirmDialog({ title: 'Delete word', text: 'Delete this library entry? Learners keep their own copies in collections.' })) { await api(`/admin/vocabulary/${del.dataset.del}`, { method: 'DELETE' }); toast('Deleted.'); reload(); }
        } catch (x) { toast(x.message, 'bad'); }
      });
      if (editing) open(editing);
    },
  };
}

async function importTab() {
  return {
    html: h`<p>Import vocabulary from CSV or JSON. Every row is validated (Tamil script, required fields, level, topic, duplicates).</p>
    <details><summary>CSV columns</summary><pre class="json">tamil,transliteration,pronunciation,english,alt_english,hindi,malayalam,part_of_speech,level,topic,register,dialect,example_ta,example_en,collocations,synonyms,antonyms
collocations format: Tamil with [[target]]|English;second|English     synonyms: word;word</pre></details>
    <form data-imp><label class="field"><span>Format</span><select name="format"><option value="csv">CSV</option><option value="json">JSON (array of entries)</option></select></label>
      <label class="field"><span>File</span><input type="file" accept=".csv,.json,text/csv,application/json" data-file></label>
      <label class="field"><span>…or paste content</span><textarea name="content" style="min-height:160px"></textarea></label>
      <label class="check"><input type="checkbox" name="publish"> Publish immediately (otherwise rows go to the review queue)</label>
      <div class="btn-row" style="margin-top:10px"><button class="btn" type="submit">Import</button></div></form><div data-out></div>`,
    mount(root) {
      const f = root.querySelector('[data-imp]');
      root.querySelector('[data-file]').addEventListener('change', async (e) => { const file = e.target.files[0]; if (file) { f.content.value = await file.text(); if (file.name.endsWith('.json')) f.format.value = 'json'; } });
      f.addEventListener('submit', async (e) => {
        e.preventDefault();
        const out = root.querySelector('[data-out]');
        try {
          const r = await api('/admin/vocabulary/import', { method: 'POST', body: { format: f.format.value, content: f.content.value, publish: f.publish.checked } });
          out.innerHTML = String(h`<div class="notice notice--info">Created ${r.created} · duplicates skipped ${r.duplicates} · rows with errors ${r.errors.length}</div>${r.errors.length ? h`<ul>${r.errors.map((x) => h`<li>Row ${x.row}: ${x.problems.join('; ')}</li>`)}</ul>` : ''}`);
        } catch (x) { out.innerHTML = String(errorsBox(x)); }
      });
    },
  };
}

async function lists() {
  const all = await api('/admin/lists');
  return {
    html: h`<form class="filters" data-new><label class="field"><span>New list title</span><input name="title" required></label><label class="field"><span>Level</span><select name="level"><option value="">—</option>${state.meta.levels.map((l) => h`<option>${l.code}</option>`)}</select></label><label class="field" style="flex:2"><span>Word IDs (comma separated)</span><input name="ids" placeholder="1, 2, 3"></label><button class="btn" type="submit">Create list</button></form>
    <div class="table-wrap" style="margin-top:12px"><table class="tbl"><tr><th>Title</th><th>Level</th><th>Words</th><th>Status</th><th>Created</th><th></th></tr>${all.map((l) => h`<tr><td>${l.title}</td><td>${l.level || ''}</td><td>${l.word_count}</td><td>${status(l.status)}</td><td class="small">${fmtDate(l.created_at)}</td><td><div class="btn-row">${l.status !== 'published' ? h`<button class="btn btn--small btn--green" data-pub="${l.id}">Publish</button>` : h`<button class="btn btn--small btn--ghost" data-unpub="${l.id}">Unpublish</button>`}<button class="btn btn--small btn--danger" data-del="${l.id}">Delete</button></div></td></tr>`)}</table></div>`,
    mount(root, reload) {
      root.querySelector('[data-new]').addEventListener('submit', async (e) => { e.preventDefault(); const d = Object.fromEntries(new FormData(e.target)); try { await api('/admin/lists', { method: 'POST', body: { title: d.title, level: d.level || null, vocabularyIds: d.ids.split(',').map((x) => Number(x.trim())).filter(Boolean) } }); toast('List created.'); reload(); } catch (x) { toast(x.message, 'bad'); } });
      root.addEventListener('click', async (e) => {
        const p = e.target.closest('[data-pub]'); const u = e.target.closest('[data-unpub]'); const d = e.target.closest('[data-del]');
        try {
          if (p) { await api(`/admin/lists/${p.dataset.pub}`, { method: 'PATCH', body: { status: 'published' } }); reload(); }
          if (u) { await api(`/admin/lists/${u.dataset.unpub}`, { method: 'PATCH', body: { status: 'pending' } }); reload(); }
          if (d && await confirmDialog({ text: 'Delete this list? Its words stay in the library.' })) { await api(`/admin/lists/${d.dataset.del}`, { method: 'DELETE' }); reload(); }
        } catch (x) { toast(x.message, 'bad'); }
      });
    },
  };
}

async function taxonomy() {
  const m = await api('/meta');
  return {
    html: h`<div class="grid grid-2"><div><h3>Topics</h3><form class="filters" data-nt><label class="field"><span>New topic</span><input name="name" required></label><label class="field"><span>Parent</span><select name="parent_id"><option value="">—</option>${m.topics.map((t) => h`<option value="${t.id}">${t.name}</option>`)}</select></label><button class="btn" type="submit">Add</button></form>
      <ul class="list">${m.topics.map((t) => h`<li class="spread"><span>${t.parentId ? '↳ ' : ''}${t.name} <span class="small muted">${t.slug}</span></span><span class="row"><button class="btn btn--small btn--ghost" data-rt="${t.id}" data-name="${t.name}">Rename</button><button class="btn btn--small btn--danger" data-dt="${t.id}">Delete</button></span></li>`)}</ul></div>
      <div><h3>Levels</h3>${m.levels.map((l) => h`<form class="win" data-lv="${l.code}" style="padding:10px;margin-bottom:10px"><strong>${l.code}</strong><label class="field"><span>Name</span><input name="name" value="${l.name}"></label><label class="field"><span>Description</span><input name="description" value="${l.description}"></label><button class="btn btn--small" type="submit">Save level</button></form>`)}
      <form class="filters" data-nl><label class="field"><span>New level code</span><input name="code" maxlength="6" required></label><label class="field"><span>Name</span><input name="name" required></label><button class="btn btn--small" type="submit">Add level</button></form></div></div>`,
    async mount(root, reload) {
      const refreshMeta = async () => { state.meta = await api('/meta'); reload(); };
      root.querySelector('[data-nt]').addEventListener('submit', async (e) => { e.preventDefault(); const d = Object.fromEntries(new FormData(e.target)); try { await api('/admin/topics', { method: 'POST', body: { name: d.name, parent_id: d.parent_id ? Number(d.parent_id) : null } }); toast('Topic added.'); refreshMeta(); } catch (x) { toast(x.message, 'bad'); } });
      root.querySelector('[data-nl]').addEventListener('submit', async (e) => { e.preventDefault(); try { await api('/admin/levels', { method: 'POST', body: Object.fromEntries(new FormData(e.target)) }); toast('Level added.'); refreshMeta(); } catch (x) { toast(x.message, 'bad'); } });
      root.querySelectorAll('[data-lv]').forEach((f) => f.addEventListener('submit', async (e) => { e.preventDefault(); try { await api(`/admin/levels/${f.dataset.lv}`, { method: 'PATCH', body: Object.fromEntries(new FormData(f)) }); toast('Level saved.'); refreshMeta(); } catch (x) { toast(x.message, 'bad'); } }));
      root.addEventListener('click', async (e) => {
        const r = e.target.closest('[data-rt]'); const d = e.target.closest('[data-dt]');
        try {
          if (r) { const name = prompt('New topic name', r.dataset.name); if (name) { await api(`/admin/topics/${r.dataset.rt}`, { method: 'PATCH', body: { name } }); refreshMeta(); } }
          if (d && await confirmDialog({ text: 'Delete this topic? Words keep existing without a topic.' })) { await api(`/admin/topics/${d.dataset.dt}`, { method: 'DELETE' }); refreshMeta(); }
        } catch (x) { toast(x.message, 'bad'); }
      });
    },
  };
}

function storyForm(s = {}) {
  const m = state.meta;
  const paras = s.paragraphs || [];
  return h`<form data-sf><div class="grid grid-2" style="gap:0 14px">
    <label class="field"><span>Tamil title *</span><input class="ta-input" name="title" value="${s.title || ''}" required></label>
    <label class="field"><span>English title</span><input name="title_en" value="${s.titleEn || ''}"></label>
    <label class="field"><span>Level *</span><select name="level">${m.levels.map((l) => h`<option ${l.code === s.level ? raw('selected') : ''}>${l.code}</option>`)}</select></label>
    <label class="field"><span>Category</span><select name="category">${m.storyCategories.map((c) => h`<option ${c === s.category ? raw('selected') : ''}>${c}</option>`)}</select></label>
    <label class="field"><span>Register</span><select name="register">${['formal', 'spoken', 'literary', 'common'].map((r) => h`<option ${r === s.register ? raw('selected') : ''}>${r}</option>`)}</select></label>
    <label class="field"><span>Source type *</span><select name="source_type">${['original', 'public-domain', 'open-license', 'ai-generated'].map((r) => h`<option ${r === (s.sourceType || 'original') ? raw('selected') : ''}>${r}</option>`)}</select></label>
    <label class="field"><span>Licence</span><input name="license" value="${s.license || ''}"></label>
    <label class="field"><span>Source / citation</span><input name="source_note" value="${s.sourceNote || ''}"></label></div>
    <label class="field"><span>Summary (English)</span><input name="summary" value="${s.summary || ''}"></label>
    <label class="field"><span>Tamil paragraphs — separate paragraphs with a blank line</span><textarea class="ta-input" name="ta" style="min-height:200px">${paras.map((p) => p.ta).join('\n\n')}</textarea></label>
    <label class="field"><span>English translation — same paragraph order</span><textarea name="en" style="min-height:160px">${paras.map((p) => p.en).join('\n\n')}</textarea></label>
    ${s.validation?.difficulty ? h`<p class="small">Text statistics: ${s.validation.difficulty.sentences} sentences, ${s.validation.difficulty.avgSentenceLength} words per sentence → suggests ${s.validation.difficulty.suggestedLevel}. ${(s.validation.warnings || []).join(' ')}</p>` : ''}
    <div data-err></div><button class="btn" type="submit">${s.id ? 'Save story' : 'Create story'}</button></form>`;
}
function readStory(f) {
  const d = Object.fromEntries(new FormData(f));
  const ta = d.ta.split(/\n\s*\n/).map((x) => x.trim()).filter(Boolean);
  const en = d.en.split(/\n\s*\n/).map((x) => x.trim());
  return { ...d, paragraphs: ta.map((t, i) => ({ ta: t, en: en[i] || '' })) };
}
async function stories({ query }) {
  const st = query.status || 'published';
  const r = await api(`/admin/stories${qs({ status: st })}`);
  const editing = query.edit ? await api(`/admin/stories/${query.edit}`) : null;
  return {
    html: h`<div class="btn-row" style="margin-bottom:10px"><button class="btn btn--bloom" data-new>Add story</button><button class="btn btn--cyan" data-gen>${state.meta.features.ai ? 'Generate a story with AI' : 'Add a batch of practice stories'}</button>
      ${['published', 'pending', 'rejected'].map((s) => h`<a class="btn btn--small ${s === st ? '' : 'btn--ghost'}" href="/admin/stories?status=${s}">${s}</a>`)}</div>
    <div class="table-wrap"><table class="tbl"><tr><th>Title</th><th>Level</th><th>Source</th><th>Status</th><th></th></tr>${r.items.map((s) => h`<tr><td><span class="ta" lang="ta">${s.title}</span><br><span class="small">${s.titleEn}</span></td><td>${s.level}</td><td class="small">${s.sourceType}</td><td>${status(s.status)}</td><td><div class="btn-row"><button class="btn btn--small btn--ghost" data-edit="${s.id}">Edit</button>${s.status !== 'published' ? h`<button class="btn btn--small btn--green" data-st="${s.id}:published">Publish</button>` : h`<button class="btn btn--small btn--ghost" data-st="${s.id}:pending">Unpublish</button>`}<button class="btn btn--small btn--danger" data-del="${s.id}">Delete</button></div></td></tr>`)}</table></div>`,
    mount(root, reload) {
      const open = (s) => modal({ title: s ? 'Edit story' : 'Add story', body: storyForm(s || {}), onMount(el, close) {
        el.querySelector('.modal')?.style.setProperty('width', 'min(860px,100%)');
        el.querySelector('[data-sf]').addEventListener('submit', async (e) => { e.preventDefault(); try { const body = readStory(e.target); if (s) await api(`/admin/stories/${s.id}`, { method: 'PATCH', body }); else await api('/admin/stories', { method: 'POST', body }); close(); toast('Story saved.'); reload(); } catch (x) { el.querySelector('[data-err]').innerHTML = String(errorsBox(x)); } });
      } });
      root.querySelector('[data-new]').addEventListener('click', () => open(null));
      root.querySelector('[data-gen]')?.addEventListener('click', async (e) => { e.target.disabled = true; toast('Generating… this can take a minute.'); try { const j = await api('/admin/jobs', { method: 'POST', body: { type: 'story' } }); toast(j.status === 'succeeded' ? (j.result?.offline ? `Added ${j.result.published} practice stories to the reading library.` : 'Story generated — it is waiting in the review queue.') : `Generation failed: ${j.error}`, j.status === 'succeeded' ? 'ok' : 'bad'); reload(); } catch (x) { toast(x.message, 'bad'); e.target.disabled = false; } });
      root.addEventListener('click', async (e) => {
        const ed = e.target.closest('[data-edit]'); const st = e.target.closest('[data-st]'); const d = e.target.closest('[data-del]');
        try {
          if (ed) open(await api(`/admin/stories/${ed.dataset.edit}`));
          if (st) { const [id, s] = st.dataset.st.split(':'); await api(`/admin/stories/${id}/status`, { method: 'POST', body: { status: s } }); reload(); }
          if (d && await confirmDialog({ text: 'Delete this story and all reading progress for it?' })) { await api(`/admin/stories/${d.dataset.del}`, { method: 'DELETE' }); reload(); }
        } catch (x) { toast(x.message, 'bad'); }
      });
      if (editing) open(editing);
    },
  };
}

async function videos({ query }) {
  const st = query.status || 'published';
  const list = await api(`/admin/videos${qs({ status: st })}`);
  const m = state.meta;
  return {
    html: h`<form class="filters" data-add><label class="field" style="flex:3"><span>YouTube link or ID</span><input name="url" required placeholder="https://www.youtube.com/watch?v=…"></label><label class="field" style="flex:2"><span>Title (if metadata can't be fetched)</span><input name="title"></label>
      <label class="field"><span>Level</span><select name="level">${m.levels.map((l) => h`<option>${l.code}</option>`)}</select></label><label class="field"><span>Category</span><select name="category">${m.videoCategories.map((c) => h`<option>${c}</option>`)}</select></label><button class="btn" type="submit">Add video</button></form>
    <p class="small muted">Videos play through the official privacy-enhanced YouTube embed. Nothing is downloaded or re-hosted.</p>
    <div class="btn-row" style="margin:8px 0">${['published', 'pending', 'rejected'].map((s) => h`<a class="btn btn--small ${s === st ? '' : 'btn--ghost'}" href="/admin/videos?status=${s}">${s}</a>`)}${state.meta.features.youtubeDiscovery ? h`<button class="btn btn--small btn--cyan" data-disc>Run discovery now</button>` : h`<span class="small muted">Automatic discovery needs YOUTUBE_API_KEY.</span>`}</div>
    <div class="table-wrap"><table class="tbl"><tr><th>Video</th><th>Level</th><th>Category</th><th>Transcript</th><th>Status</th><th></th></tr>${list.map((v) => h`<tr><td><a href="${v.watchUrl}" target="_blank" rel="noopener">${v.title}</a><br><span class="small">${v.channel} · ${v.source}</span></td><td>${v.level || '—'}</td><td>${v.category}</td><td>${v.hasTranscript ? 'yes' : '—'}</td><td>${status(v.status)}</td>
      <td><div class="btn-row"><button class="btn btn--small btn--ghost" data-edit="${v.id}">Edit</button>${v.status !== 'published' ? h`<button class="btn btn--small btn--green" data-st="${v.id}:published">Publish</button>` : h`<button class="btn btn--small btn--ghost" data-st="${v.id}:pending">Unpublish</button>`}<button class="btn btn--small btn--danger" data-del="${v.id}">Delete</button></div></td></tr>`)}</table></div>`,
    mount(root, reload) {
      root.querySelector('[data-add]').addEventListener('submit', async (e) => { e.preventDefault(); try { await api('/admin/videos', { method: 'POST', body: Object.fromEntries(new FormData(e.target)) }); toast('Video added to the review queue.'); reload(); } catch (x) { toast(x.message + (x.details?.problems ? `: ${x.details.problems.join('; ')}` : ''), 'bad'); } });
      root.querySelector('[data-disc]')?.addEventListener('click', async (e) => { e.target.disabled = true; const j = await api('/admin/jobs', { method: 'POST', body: { type: 'video_discovery', payload: { count: 3 } } }).catch((x) => ({ status: 'failed', error: x.message })); toast(j.status === 'succeeded' ? `Discovered ${j.result.added} video(s).` : `Discovery failed: ${j.error}`, j.status === 'succeeded' ? 'ok' : 'bad'); reload(); });
      root.addEventListener('click', async (e) => {
        const ed = e.target.closest('[data-edit]'); const st = e.target.closest('[data-st]'); const d = e.target.closest('[data-del]');
        try {
          if (st) { const [id, s] = st.dataset.st.split(':'); await api(`/admin/videos/${id}/status`, { method: 'POST', body: { status: s } }); reload(); }
          if (d && await confirmDialog({ text: 'Remove this video from the library?' })) { await api(`/admin/videos/${d.dataset.del}`, { method: 'DELETE' }); reload(); }
          if (ed) {
            const v = await api(`/admin/videos/${ed.dataset.edit}`);
            modal({ title: 'Edit video', body: h`<form><label class="field"><span>Title</span><input name="title" value="${v.title}"></label>
              <div class="grid grid-2" style="gap:0 12px"><label class="field"><span>Level</span><select name="level">${m.levels.map((l) => h`<option ${l.code === v.level ? raw('selected') : ''}>${l.code}</option>`)}</select></label><label class="field"><span>Category</span><select name="category">${m.videoCategories.map((c) => h`<option ${c === v.category ? raw('selected') : ''}>${c}</option>`)}</select></label>
              <label class="field"><span>Topic</span><select name="topic_id"><option value="">—</option>${m.topics.map((t) => h`<option value="${t.id}" ${t.id === v.topicId ? raw('selected') : ''}>${t.name}</option>`)}</select></label><label class="field"><span>Register</span><select name="register">${['spoken', 'formal', 'mixed', 'literary'].map((r) => h`<option ${r === v.register ? raw('selected') : ''}>${r}</option>`)}</select></label>
              <label class="field"><span>Accent / region</span><input name="accent" value="${v.accent}"></label><label class="field"><span>Duration (seconds)</span><input type="number" name="duration_seconds" value="${v.durationSeconds}"></label></div>
              <label class="field"><span>Transcript — one line each: Tamil | English (only if you are authorised to publish it)</span><textarea class="ta-input" name="transcript">${(v.transcript || []).map((l) => [l.ta, l.en].filter(Boolean).join(' | ')).join('\n')}</textarea></label>
              <label class="field"><span>Transcript source / authorisation</span><input name="transcript_source" value="${v.transcriptSource}"></label><div data-err></div><button class="btn" type="submit">Save video</button></form>`,
            onMount(el, close) { el.querySelector('form').addEventListener('submit', async (ev) => { ev.preventDefault(); const dd = Object.fromEntries(new FormData(ev.target)); const body = { ...dd, topic_id: dd.topic_id ? Number(dd.topic_id) : null, duration_seconds: Number(dd.duration_seconds) || 0, transcript: dd.transcript.trim() ? dd.transcript.split('\n').filter((x) => x.trim()).map((l) => { const [ta, en = ''] = l.split('|').map((x) => x.trim()); return { ta, en }; }) : null };
              try { await api(`/admin/videos/${v.id}`, { method: 'PATCH', body }); close(); toast('Video saved.'); reload(); } catch (x) { el.querySelector('[data-err]').innerHTML = String(errorsBox(x)); } }); } });
          }
        } catch (x) { toast(x.message, 'bad'); }
      });
    },
  };
}

async function jobs() {
  const r = await api(`/admin/jobs?lang=${state.lang}`);
  const a = r.automation;
  return {
    html: h`<p class="small">Scheduler: <strong>${a.enabled ? 'enabled' : 'disabled'}</strong> · AI: ${a.ai.configured ? a.ai.provider : 'not configured'} · YouTube: ${a.youtube.configured ? 'configured' : 'not configured'}. Each job has a unique daily key, so re-running the scheduler never duplicates content.</p>
    <div class="btn-row" style="margin-bottom:12px"><button class="btn" data-run="vocabulary">Generate ${langName()} vocabulary</button><button class="btn" data-run="story">Generate story</button><button class="btn" data-run="grammar">Generate grammar lesson</button><button class="btn" data-run="video_discovery">Discover videos</button><button class="btn btn--cyan" data-sched>Run today's scheduled jobs</button></div>
    <div class="table-wrap"><table class="tbl"><tr><th>#</th><th>Lang</th><th>Type</th><th>Status</th><th>Trigger</th><th>Created</th><th>Result / error</th><th></th></tr>${r.jobs.map((j) => h`<tr><td>${j.id}</td><td>${j.lang}</td><td>${j.type}</td><td>${status(j.status)}<br><span class="small">${j.attempts} attempt(s)</span></td><td class="small">${j.triggeredBy}</td><td class="small">${new Date(j.createdAt).toLocaleString()}</td><td class="small" style="max-width:340px">${j.error ? h`<span class="status-failed">${j.errorCode}</span> ${j.error}` : j.result ? h`<pre class="json">${JSON.stringify(j.result, null, 1)}</pre>` : ''}</td><td>${j.status === 'failed' ? h`<button class="btn btn--small" data-retry="${j.id}">Retry</button>` : ''}</td></tr>`)}</table></div>
    ${r.jobs.length ? '' : h`<p class="muted">No jobs have run yet.</p>`}`,
    mount(root, reload) {
      root.addEventListener('click', async (e) => {
        const run = e.target.closest('[data-run]'); const rt = e.target.closest('[data-retry]'); const sc = e.target.closest('[data-sched]');
        const b = run || rt || sc; if (!b) return;
        b.disabled = true; toast('Running… AI jobs can take a minute.');
        try {
          if (run) { const j = await api('/admin/jobs', { method: 'POST', body: { type: run.dataset.run } }); toast(j.status === 'succeeded' ? 'Job finished.' : `Job failed: ${j.error}`, j.status === 'succeeded' ? 'ok' : 'bad'); }
          if (rt) { const j = await api(`/admin/jobs/${rt.dataset.retry}/retry`, { method: 'POST' }); toast(j.status === 'succeeded' ? 'Retry succeeded.' : `Still failing: ${j.error}`, j.status === 'succeeded' ? 'ok' : 'bad'); }
          if (sc) { const x = await api('/admin/jobs/run-scheduler', { method: 'POST' }); toast(x.skipped ? 'Scheduler is disabled or already running.' : `Ran ${x.ran} job(s).`); }
        } catch (x) { toast(x.message, 'bad'); }
        reload();
      });
    },
  };
}

async function settings() {
  const s = await api('/admin/settings');
  const num = (k, label, hint = '') => h`<label class="field"><span>${label}</span><input type="number" min="0" name="${k}" value="${s[k]}">${hint ? h`<small>${hint}</small>` : ''}</label>`;
  return {
    html: h`<form data-set style="max-width:560px">${num('collection_word_limit', 'Maximum words per collection')}${num('daily_vocab_lists', 'New vocabulary lists per day (AI, or the offline dictionary)')}
      <div class="grid grid-2" style="gap:0 12px">${num('daily_videos_min', 'Videos per day (min)')}${num('daily_videos_max', 'Videos per day (max)')}${num('daily_stories_min', 'Stories per day (min)')}${num('daily_stories_max', 'Stories per day (max)')}</div>
      <div class="grid grid-2" style="gap:0 12px">${num('daily_grammar_min', 'Grammar lessons per day (min)')}${num('daily_grammar_max', 'Grammar lessons per day (max)')}${num('daily_topic_words_min', 'Daily Topic words (min)')}${num('daily_topic_words_max', 'Daily Topic words (max)')}</div>
      ${num('catchup_days', 'Days to catch up after downtime')}
      <p class="small muted">Targets are per language, platform-wide (not per learner).</p>
      <label class="check"><input type="checkbox" name="automation_enabled" ${s.automation_enabled ? raw('checked') : ''}> Run scheduled content automation</label><br>
      <label class="check"><input type="checkbox" name="auto_publish_validated" ${s.auto_publish_validated ? raw('checked') : ''}> Auto-publish AI content that passes validation and AI review (labelled as not human-reviewed)</label><br>
      <label class="check"><input type="checkbox" name="auto_publish_videos" ${s.auto_publish_videos ? raw('checked') : ''}> Publish discovered videos without review</label>
      <div data-err></div><div class="btn-row" style="margin-top:12px"><button class="btn" type="submit">Save settings</button></div></form>`,
    mount(root) {
      root.querySelector('[data-set]').addEventListener('submit', async (e) => {
        e.preventDefault();
        const f = e.target; const body = {};
        for (const el of f.elements) if (el.name) body[el.name] = el.type === 'checkbox' ? el.checked : Number(el.value);
        try { await api('/admin/settings', { method: 'PATCH', body }); state.meta = await api('/meta'); toast('Settings saved.'); } catch (x) { root.querySelector('[data-err]').innerHTML = String(errorsBox(x)); }
      });
    },
  };
}

